import{_ as e,o as i,c as a,a2 as r}from"./chunks/framework.ClgMjOt7.js";const h=JSON.parse('{"title":"Rust Native コア (pixiv-api)","description":"UniFFI を用いた Rust API クライアント、型バインディング、メモリ安全設計","frontmatter":{"title":"Rust Native コア (pixiv-api)","description":"UniFFI を用いた Rust API クライアント、型バインディング、メモリ安全設計"},"headers":[],"relativePath":"architecture/rust-core.md","filePath":"architecture/rust-core.md","lastUpdated":1786166106000}'),l={name:"architecture/rust-core.md"};function o(n,t,d,s,c,g){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="rust-native-コア-pixiv-api" tabindex="-1">Rust Native コア (<code>pixiv-api</code>) <a class="header-anchor" href="#rust-native-コア-pixiv-api" aria-label="Permalink to &quot;Rust Native コア (`pixiv-api`)&quot;">​</a></h1><p>Pixiv API との通信トランスポート、レスポンス JSON の検証・デコード処理は <code>rust/pixiv-api</code> クレートで実装されています。UniFFI を介した型付き Kotlin バインディング（<code>nativebridge</code>）を通して利用されます。</p><hr><h2 id="設計上のポイント" tabindex="-1">設計上のポイント <a class="header-anchor" href="#設計上のポイント" aria-label="Permalink to &quot;設計上のポイント&quot;">​</a></h2><ol><li><strong>直接的な DTO 変換</strong>: レスポンス本文を文字列として Kotlin (JVM) へ渡さず、Rust 側で <code>serde</code> により DTO へパースしてからアプリモデルへ橋渡しします。</li><li><strong>バッファサイズの安全制御</strong>: メモリ超過（OOM）や例外クラッシュを防止するため、処理バッファに上限が設定されています。</li></ol><hr><h2 id="制限値仕様" tabindex="-1">制限値仕様 <a class="header-anchor" href="#制限値仕様" aria-label="Permalink to &quot;制限値仕様&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">対象データ</th><th style="text-align:left;">上限サイズ</th><th style="text-align:left;">動作仕様</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>JSON レスポンス</strong></td><td style="text-align:left;"><strong>16 MiB</strong></td><td style="text-align:left;">デコードバッファ上限。ストリームパース時に超過した場合は処理中断</td></tr><tr><td style="text-align:left;"><strong>小説本文 (HTML)</strong></td><td style="text-align:left;"><strong>8 MiB</strong></td><td style="text-align:left;">読み込みバッファ上限</td></tr><tr><td style="text-align:left;"><strong>HTTP エラー本文</strong></td><td style="text-align:left;"><strong>64 KiB</strong></td><td style="text-align:left;">エラー解析用読み取り上限</td></tr><tr><td style="text-align:left;"><strong>例外詳細情報</strong></td><td style="text-align:left;"><strong>4 KiB</strong></td><td style="text-align:left;">Kotlin 側へ返却する例外メッセージ上限</td></tr></tbody></table><hr><h2 id="ビルドおよびツールチェーン" tabindex="-1">ビルドおよびツールチェーン <a class="header-anchor" href="#ビルドおよびツールチェーン" aria-label="Permalink to &quot;ビルドおよびツールチェーン&quot;">​</a></h2><ul><li><strong>UniFFI</strong>: UDL / proc-macro から Kotlin のインターフェースコードを生成。</li><li><strong>cargo-ndk</strong>: Android SDK の NDK を自動検出し、以下の 3 アーキテクチャ向け <code>.so</code> バイナリを出力。 <ul><li><code>aarch64-linux-android</code></li><li><code>armv7-linux-androideabi</code></li><li><code>x86_64-linux-android</code></li></ul></li><li>Gradle の <code>preBuild</code> タスクがこれらをビルドパイプラインの一部として実行します。</li></ul>',11)])])}const x=e(l,[["render",o]]);export{h as __pageData,x as default};
